#include <iostream>
#include <stdexcept>

int main() {
    try {
        throw std::runtime_error("boom");   // 派生自 std::logic_error? 不，runtime_error
    } catch (const std::logic_error& e) {    // 基类在前会吃掉派生 → 这里故意顺序正确
        std::cout << "logic: " << e.what() << '\n';
    } catch (const std::exception& e) {      // runtime_error 的基类，匹配到此
        std::cout << "base: " << e.what() << '\n';
    } catch (...) {
        std::cout << "unknown\n";
    }
}
